// Why Code: the signature needs the exact raw body, kept as binary; no node parses a form body from binary.
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers || {};
const ts = h['x-slack-request-timestamp'] || '';
const f = {};
for (const kv of raw.split('&')) { const i = kv.indexOf('='); if (i > 0) f[kv.slice(0, i)] = decodeURIComponent(kv.slice(i + 1).replace(/\+/g, ' ')); }
return [{ json: { base: `v0:${ts}:${raw}`, signature: h['x-slack-signature'] || '', fresh: Math.abs(Date.now() / 1000 - Number(ts)) <= 300,
  text: (f.text || '').trim(), user_id: f.user_id || '', user_name: f.user_name || '', team_id: f.team_id || '', app_id: f.api_app_id || '', response_url: f.response_url || '' } }];

// Why Code: parses the sub-command, matches job names and checks who may run them; a Switch would need one rule per job.
const c = $('Read the command').first().json;
const s = $('Command settings').first().json;
const ok = c.fresh && ('v0=' + $input.first().json.sig) === c.signature
  && (!s.slack_app_id || s.slack_app_id === c.app_id) && (!s.slack_team_id || s.slack_team_id === c.team_id);
const out = (o) => [{ json: { u: c.user_id, n: c.user_name, exp: String(Math.floor(Date.now() / 1000) + s.link_hours * 3600), q: '', runs: [], ...o } }];
if (!ok) return out({ action: 'refuse', status: 401, reply: 'That request did not come from this Slack app.' });
const [verb, ...rest] = c.text.split(/\s+/).filter(Boolean);
const arg = rest.join(' ').toLowerCase();
const allowed = !(s.approver_ids || []).length || s.approver_ids.includes(c.user_id);
const jobs = s.jobs || [];
const phaseName = p => (s.phases.find(x => x.phase === p) || {}).name || `Phase ${p}`;
if (!verb || verb === 'help') {
  const byPhase = {};
  for (const j of jobs.filter(j => !j.setup)) (byPhase[j.phase] = byPhase[j.phase] || []).push('`' + j.job + '`');
  const lines = Object.keys(byPhase).sort().map(p => `*${p} ${phaseName(Number(p))}*\n${byPhase[p].join('  ')}`);
  return out({ action: 'reply', reply: '*/store status*  what is waiting in every review queue\n*/store page* [queue]  a private link to the review page\n*/store run* <job>  start a job now\n*/store run setup*  run every Setup lane\n\n' + lines.join('\n\n') });
}
if (verb === 'status') return out({ action: 'status' });
if (!allowed) return out({ action: 'reply', reply: 'Only the people in approver_ids can do that. Ask one of them, or run `/store status`.' });
if (verb === 'page') return out({ action: 'page', q: arg });
if (verb === 'run') {
  let runs = arg === 'setup' ? jobs.filter(j => j.setup).sort((a, b) => a.phase - b.phase) : jobs.filter(j => j.job === arg);
  if (!runs.length) {
    const near = jobs.filter(j => !j.setup && (j.job.startsWith(arg) || arg.startsWith(j.job.split(' ')[0]))).map(j => '`' + j.job + '`');
    return out({ action: 'reply', reply: `No job called \`${arg || '(nothing)'}\`.` + (near.length ? ' Did you mean ' + near.join(', ') + '?' : ' Try `/store help`.') });
  }
  return out({ action: 'run', runs: runs.map(j => ({ job: j.job, lane: j.lane, url: s.internal_url.replace(/\/$/, '') + '/webhook/' + j.path })), reply: runs.length > 1 ? `Starting ${runs.length} jobs, one after another.` : `Starting \`${runs[0].job}\`.` });
}
return out({ action: 'reply', reply: `I don't know \`${verb}\`. Try \`/store help\`.` });

// Why Code: groups queues by phase into Slack blocks with ages and a signed link; Aggregate + Set would take five nodes.
const s = $('Command settings').first().json;
const w = $('Sign a page link').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.queue);
const ago = d => { if (!d) return ''; const h = (Date.now() - new Date(d).getTime()) / 3600000; return h < 1 ? 'under an hour' : h < 48 ? Math.round(h) + ' h' : Math.round(h / 24) + ' days'; };
const where = ch => /^[CG][A-Z0-9]{8,}$/.test(ch) ? `<#${ch}>` : ch;
const phaseName = p => (s.phases.find(x => x.phase === p) || {}).name || `Phase ${p}`;
const waiting = rows.filter(r => r.waiting > 0);
const total = waiting.reduce((a, r) => a + r.waiting, 0);
const byPhase = {};
for (const r of waiting) (byPhase[r.phase] = byPhase[r.phase] || []).push(`${r.label}: *${r.waiting}* (oldest ${ago(r.oldest)}) in ${where(r.channel)}`);
const link = `${s.page_url}?u=${encodeURIComponent(w.u)}&n=${encodeURIComponent(w.n)}&exp=${w.exp}&q=&sig=${w.link_sig}`;
const blocks = [{ type: 'section', text: { type: 'mrkdwn', text: total ? `*${total} waiting for a decision*` : ':white_check_mark: Nothing waiting for a decision.' } }];
for (const p of Object.keys(byPhase).sort()) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*${p} ${phaseName(Number(p))}*\n` + byPhase[p].join('\n') } });
if (total) blocks.push({ type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Open the review page' }, url: link, action_id: 'link_review_page' }] }, { type: 'context', elements: [{ type: 'mrkdwn', text: `Private link, works for ${s.link_hours} hours.` }] });
return [{ json: { body: { response_type: 'ephemeral', text: total ? `${total} waiting` : 'Nothing waiting', blocks } } }];

// Why Code: help, page and refusals share one reply shape, and the page answer needs the signed link built in.
const s = $('Command settings').first().json;
const w = $input.first().json;
if (w.action === 'page') {
  const link = `${s.page_url}?u=${encodeURIComponent(w.u)}&n=${encodeURIComponent(w.n)}&exp=${w.exp}&q=${encodeURIComponent(w.q)}&sig=${w.link_sig}`;
  return [{ json: { status: 200, body: { response_type: 'ephemeral', text: 'Your review page link', blocks: [
    { type: 'section', text: { type: 'mrkdwn', text: w.q ? `The *${w.q}* queue, everything waiting, up to 100 at a time.` : 'Every review queue, up to 100 waiting in each.' } },
    { type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Open the review page' }, url: link, action_id: 'link_review_page' }] },
    { type: 'context', elements: [{ type: 'mrkdwn', text: `Private to you, works for ${s.link_hours} hours.` }] } ] } } }];
}
return [{ json: { status: w.status || 200, body: { response_type: 'ephemeral', text: w.reply } } }];
